#pragma once

// A grammar header named like a file the generator writes beside its units,
// generated by both engines.

#include "cursiv/core/grammar/GrammarSpec.hpp"
#include "cursiv/core/syntax-tree/AstNode.hpp"

namespace tsibling {

struct Word : cursiv::Extends<cursiv::AstNode> {
  string_view name;
};

struct Grammar : cursiv::GrammarSpec {
  struct WS : terminal<some(s)> {};
  struct ID : terminal<some(cr<"a-z">)> {};
  struct Root : rule<create<Word>(assign<&Word::name>(ref<ID>))> {};
  using entry = Root;
  using ignore = WS;
};

struct Lr : Grammar {};
struct Ll : Grammar {};

}  // namespace tsibling
